import{At as e,Et as t,Ot as n,Zt as r,n as i,qt as a}from"./chunks/framework.B_qehzBO.js";var o=JSON.parse(`{"title":"Codificación agéntica — Dirigiendo equipos de agentes","description":"Cómo uso OpenCode, Codex, Claude Code y Hermes Agent para enviar software de producción — la visión general de mi flujo agéntico.","frontmatter":{"title":"Codificación agéntica — Dirigiendo equipos de agentes","description":"Cómo uso OpenCode, Codex, Claude Code y Hermes Agent para enviar software de producción — la visión general de mi flujo agéntico."},"headers":[],"relativePath":"es/agentic/overview/index.md","filePath":"es/agentic/overview/index.md"}`),s={name:`es/agentic/overview/index.md`};function c(i,o,s,c,l,u){let d=r(`StepBar`);return a(),t(`div`,null,[o[0]||=n(`<h1 id="codificacion-agentica-—-dirigiendo-equipos-de-agentes" tabindex="-1">Codificación agéntica — Dirigiendo equipos de agentes <a class="header-anchor" href="#codificacion-agentica-—-dirigiendo-equipos-de-agentes" aria-label="Permalink to “Codificación agéntica — Dirigiendo equipos de agentes”">​</a></h1><p>La codificación agéntica es la práctica de dirigir agentes de código autónomos como un líder técnico dirige un equipo: con especificaciones claras, ciclos de revisión ajustados y responsabilidad total. Es mi método diario para enviar software, y la considero la habilidad de ingeniería más importante que he construido en los últimos tres años.</p><p>Mi cadena de herramientas es deliberada. <strong>OpenCode</strong> para programación en pareja rápida y agnóstica del modelo en la terminal. <strong>Codex</strong> para ejecución paralela en sandboxes aisladas. <strong>Claude Code</strong> para planificación profunda y refactors en todo el código. <strong>Hermes Agent</strong> — mi propio stack — enruta modelos y orquesta a los otros tres. Herramientas distintas, fortalezas distintas, un solo flujo.</p><h2 id="el-ciclo-central" tabindex="-1">El ciclo central <a class="header-anchor" href="#el-ciclo-central" aria-label="Permalink to “El ciclo central”">​</a></h2>`,4),e(d,{items:[{title:`Informar a los agentes`},{title:`Generar e iterar`},{title:`Revisión humana`},{title:`Desplegar y monitorear`}]}),o[1]||=n(`<p>El ciclo es exactamente los cuatro pasos descritos en <a href="/Usf/es/about/how-i-work/">El método agéntico</a>: brief, generar, revisar, desplegar. Lo que cambia por herramienta es <em>dónde ocurre cada paso</em> — OpenCode vive en mi terminal junto al editor, Codex reparte el trabajo en sandboxes, Claude Code planifica antes de tocar un archivo, y Hermes coordina tareas largas y mantiene a todos alimentados con el modelo correcto.</p><h2 id="que-cambiaron-los-agentes-en-mi-ingenieria" tabindex="-1">Qué cambiaron los agentes en mi ingeniería <a class="header-anchor" href="#que-cambiaron-los-agentes-en-mi-ingenieria" aria-label="Permalink to “Qué cambiaron los agentes en mi ingeniería”">​</a></h2><ul><li><strong>Las specs se volvieron un artefacto de primera clase.</strong> Un brief preciso vale más que un prompt ingenioso.</li><li><strong>La revisión se volvió un superpoder.</strong> Leer diffs rápido — y con sospecha — es ahora una habilidad central.</li><li><strong>La arquitectura importa más, no menos.</strong> Los agentes amplifican la buena estructura y exponen la mala al instante.</li><li><strong>Los tests se pusieron serios.</strong> Si la suite es débil, los agentes producirán basura confiable con total seguridad.</li></ul><div class="info custom-block"><p class="custom-block-title">Pruebas, no promesas</p><p>Este portafolio — dos idiomas, un clon del tema VitePress, iconos SVG propios y 14 ilustraciones generadas — se construyó con este ciclo. También NetPilot, OmniRouter y cada panel de la sección de <a href="/Usf/es/projects/netpilot/">proyectos</a>.</p></div><p>Las páginas siguientes documentan cada herramienta: <a href="/Usf/es/agentic/opencode/">OpenCode</a>, <a href="/Usf/es/agentic/codex/">Codex</a>, <a href="/Usf/es/agentic/claude-code/">Claude Code</a> y <a href="/Usf/es/agentic/hermes/">Hermes Agent</a>.</p>`,5)])}var l=i(s,[[`render`,c]]);export{o as __pageData,l as default};